import java.util.*;

public class Main {
    static final int MAXN = 2002;
    static final int INF = (int)1e9;
    static int[][] cap = new int[MAXN][MAXN];
    static List<Integer>[] adj = new ArrayList[MAXN];
    static boolean[] vis = new boolean[MAXN];
    static int[] parent = new int[MAXN];

    static int[][] dir = { {1,0}, {0,1}, {-1,0}, {0,-1} };

    static {
        for (int i = 0; i < MAXN; i++) {
            adj[i] = new ArrayList<>();
        }
    }

    static int dfs(int u) {
        if (u == 1) return INF;
        vis[u] = true;
        for (int v : adj[u]) {
            if (!vis[v] && cap[u][v] > 0) {
                int flow = dfs(v);
                if (flow > 0) {
                    parent[v] = u;
                    return Math.min(flow, cap[u][v]);
                }
            }
        }
        return 0;
    }

    static int solve() {
        int totalFlow = 0;
        while (true) {
            Arrays.fill(vis, false);
            int flow = dfs(0);
            if (flow == 0) break;
            totalFlow += flow;
            int v = 1;
            while (v != 0) {
                int u = parent[v];
                cap[u][v] -= flow;
                cap[v][u] += flow;
                v = u;
            }
        }
        return totalFlow;
    }

    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        int size = sc.nextInt();
        int timeLimit = sc.nextInt();

        for (int i = 0; i < 2 * size * size + 2; i++) {
            adj[i].clear();
            for (int j = 0; j < 2 * size * size + 2; j++) {
                cap[i][j] = 0;
            }
        }

        String[] sci = new String[size];
        String[] capLab = new String[size];
        int[][][] vert = new int[size][size][2];
        int malfunctionIdx = -1;

        int N = 2;
        for (int i = 0; i < size; i++) {
            sci[i] = sc.next();
            for (int j = 0; j < size; j++) {
                char ch = sci[i].charAt(j);
                if (ch >= '1' && ch <= '9') {
                    cap[0][N] = ch - '0';
                    adj[0].add(N);
                    adj[N].add(0);
                    vert[i][j][0] = N++;
                } else if (ch == 'Z') {
                    malfunctionIdx = 100 * i + j;
                    // Replace 'Z' with 'Y' in sci array
                    StringBuilder sb = new StringBuilder(sci[i]);
                    sb.setCharAt(j, 'Y');
                    sci[i] = sb.toString();
                }
            }
        }

        int M = N;
        for (int i = 0; i < size; i++) {
            capLab[i] = sc.next();
            for (int j = 0; j < size; j++) {
                char ch = capLab[i].charAt(j);
                if (ch >= '1' && ch <= '9') {
                    cap[M][1] = ch - '0';
                    adj[M].add(1);
                    adj[1].add(M);
                    vert[i][j][1] = M++;
                }
            }
        }

        int[][] die = new int[size][size];
        for (int i = 0; i < size; i++) {
            Arrays.fill(die[i], timeLimit + 1);
        }
        if (malfunctionIdx != -1) {
            die[malfunctionIdx / 100][malfunctionIdx % 100] = 0;
        }

        Queue<Integer> q = new LinkedList<>();
        if (malfunctionIdx != -1) {
            q.offer(malfunctionIdx);
        }
        while (!q.isEmpty()) {
            int x = q.poll();
            int y = x % 100;
            x /= 100;
            for (int[] d : dir) {
                int nx = x + d[0];
                int ny = y + d[1];
                if (nx >= 0 && nx < size && ny >= 0 && ny < size && sci[nx].charAt(ny) != 'Y' && die[nx][ny] > die[x][y] + 1) {
                    die[nx][ny] = die[x][y] + 1;
                    q.offer(100 * nx + ny);
                }
            }
        }

        int[][] reach = new int[size][size];
        for (int i = 0; i < size; i++) {
            Arrays.fill(reach[i], timeLimit + 1);
        }

        for (int i = 0; i < size; i++) {
            for (int j = 0; j < size; j++) {
                if (sci[i].charAt(j) >= '1' && sci[i].charAt(j) <= '9') {
                    for (int x = 0; x < size; x++) {
                        Arrays.fill(reach[x], timeLimit + 1);
                    }
                    reach[i][j] = 0;
                    if (capLab[i].charAt(j) >= '1' && capLab[i].charAt(j) <= '9') {
                        cap[vert[i][j][0]][vert[i][j][1]] = INF;
                        adj[vert[i][j][0]].add(vert[i][j][1]);
                        adj[vert[i][j][1]].add(vert[i][j][0]);
                    }
                    Queue<Integer> q2 = new LinkedList<>();
                    q2.offer(100 * i + j);
                    while (!q2.isEmpty()) {
                        int x = q2.poll();
                        int y = x % 100;
                        x /= 100;
                        for (int[] d : dir) {
                            int nx = x + d[0];
                            int ny = y + d[1];
                            if (nx >= 0 && nx < size && ny >= 0 && ny < size && sci[nx].charAt(ny) != 'Y' && reach[nx][ny] > reach[x][y] + 1) {
                                if (capLab[nx].charAt(ny) >= '1' && capLab[nx].charAt(ny) <= '9') {
                                    if (reach[x][y] + 1 <= die[nx][ny]) {
                                        cap[vert[i][j][0]][vert[nx][ny][1]] = INF;
                                        adj[vert[i][j][0]].add(vert[nx][ny][1]);
                                        adj[vert[nx][ny][1]].add(vert[i][j][0]);
                                    }
                                }
                                if (reach[x][y] + 1 < die[nx][ny]) {
                                    reach[nx][ny] = reach[x][y] + 1;
                                    q2.offer(100 * nx + ny);
                                }
                            }
                        }
                    }
                }
            }
        }

        System.out.println(solve());
        sc.close();
    }
}
